/**
 * Delivery state of an outbound DM bubble, mirrored from
 * [`fetchit_chat::outbox::OutboxStatus`] for the uniffi surface.
 */

enum class OutboxStatusFfi {
    
    /**
     * Send attempted, not yet confirmed delivered.
     */
    SENDING,
    /**
     * Recipient acknowledged delivery.
     */
    DELIVERED,
    /**
     * The attempt errored or timed out; eligible for retry.
     */
    FAILED;
    companion object
}


/**
 * @suppress
 */
public object FfiConverterTypeOutboxStatusFfi: FfiConverterRustBuffer<OutboxStatusFfi> {
    override fun read(buf: ByteBuffer) = try {
        OutboxStatusFfi.values()[buf.getInt() - 1]
    } catch (e: IndexOutOfBoundsException) {
        throw RuntimeException("invalid enum value, something is very wrong!!", e)
    }

    override fun allocationSize(value: OutboxStatusFfi) = 4UL

    override fun write(value: OutboxStatusFfi, buf: ByteBuffer) {
        buf.putInt(value.ordinal + 1)
    }
}





/**
 * FFI-shaped rendition.
 */
sealed class RenditionFfi {
    
    /**
     * Plain text, optionally tagged with a language.
     */
    data class Text(
        /**
         * Optional language tag.
         */
        val `language`: kotlin.String?, 
        /**
         * Decoded UTF-8 body.
         */
        val `body`: kotlin.String) : RenditionFfi() {
        companion object
    }
    
    /**
     * A still image. `data` is raw encoded bytes.
     */
    data class Image(
        /**
         * IANA MIME.
         */
        val `mime`: kotlin.String, 
        /**
         * Raw encoded image bytes.
         */
        val `data`: kotlin.ByteArray) : RenditionFfi() {
        companion object
    }
    
    /**
     * An audio asset.
     */
    data class Audio(
        /**
         * IANA MIME.
         */
        val `mime`: kotlin.String, 
        /**
         * Raw encoded audio bytes.
         */
        val `data`: kotlin.ByteArray) : RenditionFfi() {
        companion object
    }
    
    /**
     * A video asset.
     */
    data class Video(
        /**
         * IANA MIME.
         */
        val `mime`: kotlin.String, 
        /**
         * Raw encoded video bytes.
         */
        val `data`: kotlin.ByteArray) : RenditionFfi() {
        companion object
    }
    
    /**
     * A PDF document.
     */
    data class Pdf(
        /**
         * Raw PDF bytes.
         */
        val `data`: kotlin.ByteArray) : RenditionFfi() {
        companion object
    }
    
    /**
     * JSON, pre-pretty-printed for display.
     */
    data class Json(
        /**
         * Pretty-printed JSON string. The original tree shape is not
         * preserved across the FFI boundary; UI code that needs it
         * can re-parse with the platform JSON library.
         */
        val `prettyPrinted`: kotlin.String) : RenditionFfi() {
        companion object
    }
    
    /**
     * Tabular data (CSV-style).
     */
    data class Tabular(
        /**
         * Column headers.
         */
        val `columns`: List<kotlin.String>, 
        /**
         * Rows aligned with `columns`.
         */
        val `rows`: List<List<kotlin.String>>) : RenditionFfi() {
        companion object
    }
    
    /**
     * Archive index. Extraction is a UI concern.
     */
    data class Archive(
        /**
         * One entry per archive member.
         */
        val `entries`: List<ArchiveEntryFfi>) : RenditionFfi() {
        companion object
    }
    
    /**
     * An etch/it envelope.
     */
    data class EtchitEnvelope(
        /**
         * Envelope title.
         */
        val `title`: kotlin.String, 
        /**
         * Decoded content.
         */
        val `content`: kotlin.String, 
        /**
         * Optional language tag.
         */
        val `language`: kotlin.String?) : RenditionFfi() {
        companion object
    }
    
    /**
     * A self-contained HTML document -- render in a `WebView`.
     */
    data class Html(
        /**
         * Raw HTML source.
         */
        val `body`: kotlin.String) : RenditionFfi() {
        companion object
    }
    
    /**
     * Bytes the registry could not classify any more specifically.
     */
    data class OpaqueBinary(
        /**
         * Best-effort MIME guess.
         */
        val `mime`: kotlin.String, 
        /**
         * Raw bytes.
         */
        val `data`: kotlin.ByteArray) : RenditionFfi() {
        companion object
    }
    

    
    companion object
}

